R\r\nIP-NNNNNNNNNNNNNNN-WMI\r\n\r\nThe ‘n’ string consists of a maximum 15 characters restricted to using the characters 0-9, A-Z 且 the underscore character ‘_’,\r\nAND ‘x’ is set to ‘1’ 或 ‘0’\r\n\r\n当车型= M2x, M3x, N2x, N3x, Ox, Lx, Tx, Cx ,Rx, Sx时禁止','minLength=1; maxLength=100','0.2.3.','DIRECT',34,'VALUE REGEX','认证系统','c3175a09-71fd-4c44-baa6-ac5ab7bbc231'),(2224,39,'VehicleCategory','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'XSD中必填','maxLength=10','0.4.','DIRECT',34,'VALUE IS PRESENT','认证系统','38861e73-0a76-4c46-aad8-5a4ea62ff877'),(2225,40,'ManufacturerStageNumber','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'XSD中必填\r\nNumber must be sequential starting with 1','min=0.0; max=99.0',NULL,NULL,34,'VALUE IS PRESENT',NULL,'7f72bfdd-efbf-4baf-bae7-f852c8bd0b3d'),(2226,41,'ManufacturerName','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'XSD中必填','minLength=1; maxLength=150','0.5.','DIRECT',34,'VALUE IS PRESENT','认证系统','5d83841c-0ce6-419e-8399-f4cd04665b42'),(2227,42,'ManufacturerAddressLine1','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'XSD中必填','minLength=1; maxLength=150','0.5.','DIRECT',34,'VALUE IS PRESENT','认证系统','89b35104-fc7c-4b3d-ab29-29690e14da8a'),(2228,43,'ManufacturerAddressLine2','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,NULL,'minLength=1; maxLength=150','0.5.','DIRECT',34,'VALUE IS PRESENT','认证系统','38fb3672-f246-4637-9bb9-5616b5a5d8d4'),(2229,44,'ManufacturerAddressLine3','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,NULL,'minLength=1; maxLength=150','0.5.','STRIP_UNIT:2',34,'VALUE IS PRESENT','认证系统','00db2fb7-f59a-4124-a002-62868c0332d5'),(2230,45,'ManufacturerPlaceOfResidence','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'XSD中必填','minLength=1; maxLength=80','0.5.','DIRECT',34