String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'C\', @StageOfCompletion = \'V\'','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx 且 完成阶段=C（完整车）时必填\r\n\r\n当车型= Ox, Lx, Tx, Cx, Rx, Sx时禁止','maxLength=1',NULL,'DIRECT',34,'VALUE IS PRESENT IF','认证系统','c78a7a09-320c-4ae1-9aa6-6c61512fe0eb'),(2254,69,'SignatureLocation','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'XSD中必填','minLength=1; maxLength=80',NULL,'DIRECT',34,'VALUE IS PRESENT','认证系统','695b48b5-f379-4427-a381-034be0556daa'),(2255,70,'SignatureDate','Date','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'XSD中必填',NULL,NULL,'DATE_FORMAT:dd/MM/yyyy',34,'VALUE IS PRESENT','MES','e5a3e752-1105-450f-887b-b34525fe2cc1'),(2256,71,'NumberOfAxles','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nR2:VALUE > 1\r\nR3:VALUE = COUNT(AxleGroup)','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox, Lx, Tx, Rx, Sx时必填\r\n\r\nNumberOfAxles > 1 where  VehicleCategory = Mx, Nx, Lx, Tx, Rx, Sx\r\nNumberOfAxles must be equal to sum of axles in the AxleTable','min=0.0; max=99.0','1.','STRIP_UNIT',34,'VALUE IS PRESENT','认证系统','5938c800-c6c4-438e-a215-ba6a6489e364'),(2257,72,'NumberOfWheels','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nR2:VALUE >= 1\r\nR3:VALUE >= 2\r\nR4:VALUE >= 3\r\nR5:VALUE >= 4','N','0','admin',NULL,'',NULL,'必填 where  VehicleCategory = Mx, Nx, Ox, Lx, Tx, Rx, Sx\r\n\r\nNumberOfWheels >= 1 where VehicleCategory = Ox, Rx, Sx\r\nNumberOfWheels >= 2 where VehicleCategory = Lx\r\nNumberOfWheels >= 3 where VehicleCategory = Tx\r\nNumberOfWheels >= 4 where VehicleCategory = Mx, Nx','min=0.0; max=99.0','1.','STRIP_UNIT:2',34,'VALUE IS PRESENT','认证系统','ac0e23dd-327d-4d7c-b4e5-79924022aac5'),(2258,73,'NumberOfPoweredAxles','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nR2:VALUE IS PRESENT IF ANY PoweredAxleIndicator = \'Y\'\r\nR3:VALUE = COUNT(PoweredAxleIndicator WITHIN [\'Y\'])','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Tx, Cx with any PoweredAxleIndicator = Y时必填\r\nNumberOfPoweredAxles is the sum of the PoweredAxleIndicator = Y\r\n\r\n当车型=Ox, Lx, Rx, Sx时禁止','min=0.0; max=99.0','3.','STRIP_UNIT',34,'VALUE IS PRESENT IF','认证系统','8eaa4b01-363b-4716-af56-064bd449a3ce'),(2259,74,'PoweredAxleIndicator','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Lx, Tx, Cx时必填\r\nCount of PoweredAxleIndicator with value Y has to be equal to value in NumberOfPoweredAxles\r\n\r\n当车型=Ox, Rx, Sx时禁止','maxLength=1','3.','DIRECT',34,'VALUE IS PRESENT','认证系统','9114108e-7b55-4b21-8aae-61f88289a909'),(2260,75,'InterconnectionWithPoweredAxleNumber','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Ox, Lx, Tx, Cx, Rx, Sx时禁止','min=0.0; max=9999.0','3.','DIRECT',34,'VALUE IS PRESENT',NULL,'3edda31e-6609-455a-8724-d8605e68d4fb'),(2261,76,'InterconnectionWithPoweredAxleConnection','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Ox, Lx, Tx, Cx, Rx, Sx时禁止','maxLength=5','3.','DIRECT',34,'VALUE IS PRESENT',NULL,'8905b515-b62b-43b0-9cf7-128d08e4ca1a'),(2262,77,'AutomatedVehicle','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx 且 完成阶段=C（完整车）时必填\r\n\r\n当车型=Ox, Lx, Tx, Cx, Rx, Sx时禁止','maxLength=5','3.1.','DIRECT',34,'VALUE IS PRESENT','认证系统','85494ec1-7316-467d-b855-ba551a90375b'),(2263,78,'Wheelbase','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nR2:VALUE-RANGE IS PRESENT\r\nR3:VALUE-RANGE IS VALID','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Lx, Tx 且 完成阶段=C（完整车）时必填\r\n当车型=Ox, Rx, Sx 且  WheelbaseAdjustableMin / WheelbaseAdjustableMax has no value 且 完成阶段=C（完整车）时必填\r\n\r\n当 WheelbaseAdjustableMin / WheelbaseAdjustableMax 有值时禁止','min=0.0; max=99999.0','4.','STRIP_UNIT',34,'VALUE IS PRESENT','认证系统','86531c93-258b-4870-a403-d5112b455c23'),(2264,79,'AxleSpacing','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nR2:VALUE-RANGE IS PRESENT IF AxleNumber < COUNT(^2:AxleGroup)\r\nR3:VALUE IS ABSENT IF AxleNumber = COUNT(^2:AxleGroup)','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox, Rx, Sx 且 AxleSpacingAdjustableMin / AxleSpacingAdjustableMax has no value时必填\r\n\r\n禁止 for the last axle\r\n当车型=Lx, Tx, Cx时禁止\r\n当 AxleSpacingAdjustableMin/AxleSpacingAdjustableMax 有值时禁止','min=0.0; max=99999.0','4.1.','STRIP_UNIT',34,'VALUE IS ABSENT IF','认证系统','0dd04b49-f85a-45f3-9ec3-43cc99bfc242'),(2265,80,'AxleSpacingAdjustableMin','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nVALUE IS ABSENT IF AxleNumber = COUNT(^2:AxleGroup)','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox, Rx, Sx 且 AxleSpacingAdjustable has no value时必填\r\nAxleSpacingAdjustableMin < AxleSpacingAdjustableMax\r\n\r\n禁止 for the last axle\r\n当车型=Lx, Tx, Cx时禁止\r\n当 AxleSpacingAdjustable 有值时禁止','min=0.0; max=99999.0','4.1.',NULL,34,'VALUE IS ABSENT IF',NULL,'d851cc07-0d35-46e6-8179-6535554848d8'),(2266,81,'AxleSpacingAdjustableMax','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nVALUE IS ABSENT IF AxleNumber = COUNT(^2:AxleGroup)','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox, Rx, Sx 且 AxleSpacingAdjustable has no value时必填\r\nAxleSpacingAdjustableMax > AxleSpacingAdjustableMin\r\n\r\n禁止 for the last axle\r\n当车型=Lx, Tx, Cx时禁止\r\n当 AxleSpacingAdjustable 有值时禁止','min=0.0; max=99999.0','4.1.',NULL,34,'VALUE IS ABSENT IF',NULL,'2fc823ea-2eac-4b95-9dd8-aa9060ba89f5'),(2267,82,'Length','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'C\', @StageOfCompletion = \'V\'\r\nR2:VALUE-RANGE IS PRESENT\r\nR3:VALUE-RANGE IS VALID\r\nR4:VALUE <= 12000\r\nR5:VALUE <= 18750\r\nR6:VALUE <= 12000\r\nR7:VALUE <= 14000','N','0','admin',NULL,'',NULL,'当车型=Mx, N1x, Lx 且 完成阶段=C（完整车）时必填\r\n当车型=N2x, N3x, Ox, Tx, Cx, Rx, Sx 且 LengthAdjustableMin / LengthAdjustableMax has no value 且 完成阶段=C（完整车） 时必填\r\n\r\n\r\nLength <= 12000 where VehicleCategory = M1x, N1x 且 MaximumAuthorisedDimensionsDerogationIndicator = N\r\nLength <= 18750 where VehicleCategory = M2x, M3x 且 MaximumAuthorisedDimensionsDerogationIndicator = N\r\nLength <= 12000 where VehicleCategory = N2x, N3x 且 ElongatedCabIndicator = N 且 MaximumAuthorisedDimensionsDerogationIndicator = N\r\nLength <= 14000 where VehicleCategory = N2x, N3x  且 ElongatedCabIndicator = Y 且 MaximumAuthorisedDimensionsDerogationIndicator = N\r\n\r\n当 LengthAdjustableMin/LengthAdjustableMax 有值时禁止\r\n禁止 where where VehicleCategory = Mx, Nx,  Ox, Tx, Cx, Rx, Sx 且 完成阶段=I（不完整车）','min=0.0; max=99999.0','5.','STRIP_UNIT',34,'VALUE IS PRESENT IF','认证系统','049fa480-755c-4318-a486-5e00506a8fc9'),(2268,83,'MaximumPermissibleLength','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'I\'','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox 且 StageOf Completion = I时必填\r\n当车型=Tx, Cx, Rx, Sx 且 MaximumPermissibleLengthMin / MaximumPermissibleLengthMax has no value 且 StageOf Completion = I时必填\r\n\r\n当车型=Lx时禁止\r\n当完成阶段=C, V时禁止\r\n当 MaximumPermissibleLengthMin / MaximumPermissibleLengthMax 有值时禁止','min=0.0; max=99999.0','5.1.',NULL,34,'VALUE IS PRESENT IF',NULL,'d2b5555c-059f-4815-82cb-3d9dbcf14683'),(2269,84,'Width','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'C\', @StageOfCompletion = \'V\'\r\nR2:VALUE-RANGE IS PRESENT\r\nR3:VALUE-RANGE IS VALID\r\nR4:VALUE <= 2550\r\nR5:VALUE <= 2600','N','0','admin',NULL,'',NULL,'当车型=Mx, N1, Lx 且 完成阶段=C（完整车）时必填\r\n当车型=N2x, N3x, Ox, Tx, Cx, Rx, Sx 且 LengthAdjustableMin / LengthAdjustableMax has no value 且 完成阶段=C（完整车）时必填\r\n\r\nWidth <= 2550 where VehicleCategory = Mx 且 MaximumAuthorisedDimensionsDerogationIndicator = N\r\nWidth <= 2600 where VehicleCategory = Nx, Ox 且 MaximumAuthorisedDimensionsDerogationIndicator = N\r\n\r\n当车型=Mx, Nx, Ox, Tx, Cx, Rx, Sx 且 完成阶段=I（不完整车）时禁止\r\n当 LengthAdjustableMin/LengthAdjustableMax 有值时禁止','min=0.0; max=9999.0','6.','STRIP_UNIT',34,'VALUE IS PRESENT IF','认证系统','00787fe6-9de6-4bae-b36c-436753c5c4ed'),(2270,85,'MaximumPermissibleWidth','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'I\'','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox, 且 完成阶段=I（不完整车）时必填\r\n当车型=Tx, Cx, Rx, Sx  且 MaximumPermissibleWidthMin / MaximumPermissibleWidthMax has no value 且 完成阶段=I（不完整车） 时必填\r\n\r\n禁止 where VehicleCode = Lx\r\n当完成阶段=C, V时禁止\r\n当 MaximumPermissibleWidthMin / MaximumPermissibleWidthMax 有值时禁止','min=0.0; max=9999.0','6.1.',NULL,34,'VALUE IS PRESENT IF',NULL,'2bc978cb-ef97-4b1b-875d-f55f72309693'),(2271,86,'Height','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'C\', @StageOfCompletion = \'V\'\r\nR2:VALUE <= 4000\r\nR3:VALUE-RANGE IS PRESENT\r\nR4:VALUE-RANGE IS VALID','N','0','admin',NULL,'',NULL,'当车型=Mx, N1x, Ox, Lx, Tx, Cx, Rx, Sx 且 HeightAdjustableMin / HeightAdjustableMax has no value 且 完成阶段=C（完整车）时必填\r\n\r\nHeight <= 4000  if MaximumAuthorisedDimensionsDerogationIndicator = N\r\n\r\n当车型=Mx, Nx, Ox, Tx, Cx, Rx, Sx 且 完成阶段=I（不完整车）时禁止\r\n当 HeightAdjustableMin / HeightAdjustableMax 有值时禁止','min=0.0; max=9999.0','7.','STRIP_UNIT',34,'VALUE IS PRESENT IF','认证系统','fd1eea25-4552-4ffe-8ae3-29d11f9f686b'),(2272,87,'HeightAdjustableMin','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'C\', @StageOfCompletion = \'V\'','N','0','admin',NULL,'',NULL,'当车型=Mx, N1x, Ox, Lx, Tx, Cx, Rx, Sx 且 Height has no value 且 完成阶段=C（完整车）时必填\r\nHeightAdjustableMin < HeightAdjustableMax\r\n\r\n禁止 where where VehicleCategory = Mx, Nx, Ox, Tx, Cx, Rx, Sx 且 完成阶段=I（不完整车）\r\n当 Height 有值时禁止','min=0.0; max=9999.0','7.',NULL,34,'VALUE IS PRESENT IF',NULL,'028023f1-c873-4c48-a48f-16caee5a569b'),(2273,88,'HeightAdjustableMax','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'C\', @StageOfCompletion = \'V\'\r\nVALUE <= 4000','N','0','admin',NULL,'',NULL,'当车型=Mx, N1x, Ox, Lx, Tx, Cx, Rx, Sx 且 Height has no value 且  完成阶段=C（完整车）时必填\r\nHeightAdjustableMax <= 4000  且 MaximumAuthorisedDimensionsDerogationIndicator = N \r\nHeightAdjustableMax > HeightAdjustableMin\r\n\r\n禁止 where where VehicleCategory = Mx, Nx, Ox, Tx, Cx, Rx, Sx 且 完成阶段=I（不完整车）\r\n当 Height 有值时禁止','min=0.0; max=9999.0','7.',NULL,34,'VALUE IS PRESENT IF',NULL,'7e8cc7bc-f664-45d1-bc35-ea94eef92ab8'),(2274,89,'MaximumPermissibleHeight','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'I\'','N','0','admin',NULL,'',NULL,'当车型=Mx, N1x, Ox 且 StageOfCompletion =  I时必填\r\n当车型=Tx, Cx, Rx, Sx 且 StageOfCompletion =  I 且 MaximumPermissibleHeightMin / MaximumPermissibleHeightMax has no value时必填\r\n\r\n当完成阶段= C, V时禁止\r\n当车型= N2x, N3x, Lx时禁止\r\n当 MaximumPermissibleHeightMin / MaximumPermissibleHeightMax 有值时禁止','min=0.0; max=9999.0','7.1.',NULL,34,'VALUE IS PRESENT IF',NULL,'58e80ef4-18f3-45db-a972-ce970a614721'),(2275,90,'MaximumPermissibleRearOverhang','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'I\'','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox  且 StageOf Completion = I时必填\r\n\r\n当车型=Mx, Nx, Ox  且 StageOf Completion = C, V时禁止\r\n当车型=Lx, Tx, Cx, Rx, Sx时禁止','min=0.0; max=9999.0','12.1.',NULL,34,'VALUE IS PRESENT IF',NULL,'aa10fc69-c276-4588-9e84-e8bc88a1fefd'),(2276,91,'MassInRunningOrder','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'C\', @StageOfCompletion = \'V\'\r\nR2:VALUE-RANGE IS PRESENT\r\nR3:VALUE-RANGE IS VALID','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox, Lx 且 完成阶段=C（完整车）时必填\r\n当车型=Tx, Cx, Rx, Sx 且 MassInRunningOrderVariableMin / MassInRunningOrderVariableMax has no value 且 完成阶段=C（完整车）时必填\r\n\r\n当 MassInRunningOrderVariableMin / MassInRunningOrderVariableMax 有值时禁止','min=0.0; max=999999.0','13.','STRIP_UNIT',34,'VALUE IS PRESENT IF','认证系统','8dc9eb2f-b4b4-4134-b9d6-0adb005e2aa5'),(2277,92,'ActualMass','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'C\', @StageOfCompletion = \'V\'\r\nVALUE < TechnicallyPermissibleMaximumLadenMass?','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox, Lx 且 完成阶段=C（完整车）时必填\r\nValue must be less then TechnicallyPermissibleMaximumLadenMass where VehicleCategory = Mx, Nx, Ox, Lx\r\n\r\n当完成阶段=I时禁止\r\n当车型=Tx, Cx, Rx, Sx时禁止','min=0.0; max=999999.0','13.2.','STRIP_UNIT',34,'VALUE IS PRESENT IF','认证系统','96dafb93-4276-4c75-b23d-b5f7c3d5f5c9'),(2278,93,'MassInRunningOrderIncomplete','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'V\', @StageOfCompletion = \'I\'','N','0','admin',NULL,'',NULL,NULL,'min=0.0; max=999999.0','14.',NULL,34,'VALUE IS PRESENT IF',NULL,'f767f19f-375b-479f-b52b-e7a406ea8d11'),(2279,94,'DistributionMassIncompleteAxle','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'I\'','N','0','admin',NULL,'',NULL,NULL,'min=0.0; max=99999.0','14.1.',NULL,34,'VALUE IS PRESENT IF',NULL,'6086cd7f-2a4b-4a57-a07e-642930919135'),(2280,95,'MinimumMassCompleted','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'I\'','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox 且 完成阶段=I（不完整车）时必填\r\n\r\n当车型=Mx, Nx, Ox 且 完成阶段=C（完整车）, V时禁止\r\n当车型=Lx, Tx, Cx, Rx时禁止','min=0.0; max=999999.0','15.',NULL,34,'VALUE IS PRESENT IF',NULL,'b1b131ec-e310-42ac-b49a-b23aa7df9f10'),(2281,96,'MinimalPermissibleDistributionMassCompletedAxle','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'I\'','N','0','admin',NULL,'',NULL,NULL,'min=0.0; max=99999.0','15.1.',NULL,34,'VALUE IS PRESENT IF',NULL,'3b91b88d-2d88-4f48-8a1d-893b930f373a'),(2282,97,'TechnicallyPermissibleMaximumLadenMass','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nR2:VALUE-RANGE IS PRESENT\r\nR3:VALUE <= SUM?(COALESCE(TechnicallyPermissibleMassAxle, TechnicallyPermissibleMassAxleAdjustableMax?))\r\nR4:VALUE <= SUM?(COALESCE(TechnicallyPermissibleMassAxle, TechnicallyPermissibleMassAxleAdjustableMax?)) + SUM?(TechnicallyPermissibleMaximumStaticVerticalMassCouplingPoint)','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox, Lx 且 完成阶段=C（完整车）时必填\r\n当车型=Tx, Cx, Rx, Sx 且 TechnicallyPermissibleMaximumLadenMassVariableMin / TechnicallyPermissibleMaximumLadenMassVariableMax has no value 且 完成阶段=C（完整车）时必填\r\n\r\nSum of all TechnicallyPermissibleMassAxle >= TechnicallyPermissibleMaximumLadenMass where VehicleCategory = Mx, Nx, Lx, Tx\r\nSum of all TechnicallyPermissibleMassAxle 且 TechnicallyPermissibleMaximumStaticVerticalMassCouplingPoint >= TechnicallyPermissibleMaximumLadenMass where VehicleCategory = Ox\r\n\r\n当 TechnicallyPermissibleMaximumLadenMassVariableMin / TechnicallyPermissibleMaximumLadenMassVariableMax 有值时禁止','min=0.0; max=999999.0','16.1.','STRIP_UNIT',34,'VALUE IS PRESENT','认证系统','c6775b90-6ba8-446c-8411-f53f487c8473'),(2283,98,'TechnicallyPermissibleMassAxle','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nR2:VALUE-RANGE IS PRESENT\r\nR3:VALUE-RANGE IS VALID','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox, Lx, Tx 且 TechnicallyPermissibleMassAxleAdjustableMax / TechnicallyPermissibleMassAxleAdjustableMin has no value时必填\r\n\r\n当 且 TechnicallyPermissibleMassAxleAdjustableMin / TechnicallyPermissibleMassAxleAdjustableMax 有值时禁止','min=0.0; max=99999.0','16.2','DIRECT',34,'VALUE IS PRESENT',NULL,'ab39c005-ed0e-4bff-92ba-dc371180e49f'),(2284,99,'TechnicallyPermissibleMassAxleAdjustableMin','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Ox, Lx, Tx 且 TechnicallyPermissibleMassAxle has no value时必填\r\nTechnicallyPermissibleMassAxleAdjustableMin < TechnicallyPermissibleMassAxleAdjustableMax\r\n\r\n当 TechnicallyPermissibleMassAxle 有值时禁止','min=0.0; max=99999.0','16.2',NULL,34,'VALUE IS PRESENT',NULL,'aa9affcf-08f3-4052-9de0-5ff837e44b12'),(2285,100,'TechnicallyPermissibleMassAxleAdjustableMax','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Mx , Nx, Ox, Lx, Tx 且 TechnicallyPermissibleMassAxle has no value时必填\r\nTechnicallyPermissibleMassAxleAdjustableMax < TechnicallyPermissibleMassAxleAdjustableMin\r\n\r\nSum of all TechnicallyPermissibleMassAxle => TechnicallyPermissibleMassAxleAdjustableMax\r\n\r\n当 TechnicallyPermissibleMassAxle 有值时禁止','min=0.0; max=99999.0','16.2',NULL,34,'VALUE IS PRESENT',NULL,'d08a4ee5-d5b0-44fe-9fc1-a9360c3e8f57'),(2286,101,'TechnicallyPermissibleMaximumCombinationMass','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'必填 in at least one group within the TowingBrakedTypeTrailTable where VehicleCategory = Mx, Nx, Lx, Tx, Cx 且 TechnicallyPermissibleMaximumTowableMass exists anywhere within the TowingBrakedTypeTrailTable 且 完成阶段=C（完整车）\r\n\r\n当车型=Ox时禁止','min=0.0; max=999999.0','16.4.','STRIP_UNIT',34,'VALUE IS PRESENT','认证系统','8a950808-df86-4937-8475-9f8a361525f8'),(2287,102,'BodyworkTypeTrailer','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nVALUE IS PRESENT IF TechnicallyPermissibleMaximumTowableMass IS PRESENT AND BrakedTypeTrail = \'BRK\'','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx 且 BrakedTypeTrail = BRK 且 TechnicallyPermissibleMaximumTowableMass has a value within the same TowingBrakedTypeTrailGroup  且 完成阶段=C（完整车）时必填\r\n当车型=Tx, Cx, Rx, Sx 且 完成阶段=C（完整车）时必填\r\n\r\n当车型=Lx, Ox时禁止','maxLength=3','18.1.',NULL,34,'VALUE IS PRESENT IF','认证系统','991d551f-fef5-4c7a-a840-30587c2c3b31'),(2288,103,'BodyworkTypeTrailer','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nVALUE IS PRESENT IF TechnicallyPermissibleMaximumTowableMass IS PRESENT AND BrakedTypeTrail = \'BRK\'','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx 且 BrakedTypeTrail = BRK 且 TechnicallyPermissibleMaximumTowableMass has a value within the same TowingBrakedTypeTrailGroup  且 完成阶段=C（完整车）时必填\r\n当车型=Tx, Cx, Rx, Sx 且 完成阶段=C（完整车）时必填\r\n\r\n当车型=Lx, Ox时禁止','maxLength=3','18.2.',NULL,34,'VALUE IS PRESENT IF','认证系统','991d551f-fef5-4c7a-a840-30587c2c3b31'),(2289,104,'BodyworkTypeTrailer','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nVALUE IS PRESENT IF TechnicallyPermissibleMaximumTowableMass IS PRESENT AND BrakedTypeTrail = \'BRK\'','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx 且 BrakedTypeTrail = BRK 且 TechnicallyPermissibleMa