,(2472,287,'TyreFittedProductionIndicator','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型= Mx, Nx, Ox 且 完成阶段=C（完整车）时必填\r\nExactly one has to have the value Y\r\n\r\n当车型=Lx, Tx, Cx, Rx, Sx时禁止','maxLength=1','35.',NULL,34,'VALUE IS PRESENT','认证系统','80ae37df-8ed2-4fcd-a561-3ec91185b8a7'),(2473,288,'TyreMaximumSpeedIndicator','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=M1x, N1x, L3x, L4x, L5x, L7x 且 完成阶段=C（完整车）时必填\r\n\r\n当车型= M2x, M3x, N2x,  N3x ,Ox, L1x, L2x, L6x, Tx, Cx, Rx, Sx时禁止','maxLength=1','35.',NULL,34,'VALUE IS PRESENT','认证系统','e4a45c8f-ac57-4a84-b903-1a1cf7220e93'),(2474,289,'TyreType','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Tx, Cx, Rx, Sx时禁止','maxLength=7','35.',NULL,34,'VALUE IS PRESENT','认证系统','132ea956-729d-4f64-90de-f42e1e245e2f'),(2475,290,'RollingResistanceClass','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Cx时禁止','maxLength=1','35.','DIRECT',34,'VALUE IS PRESENT','认证系统','a886197b-7a60-48a7-af28-3c1de86a3a52'),(2476,291,'TrailerBrakeControlSystemTechnology','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Lx时禁止','maxLength=5','36.','DIRECT',34,'VALUE IS PRESENT','认证系统','d65f0c57-8dcc-44c6-8f0c-bda9ee29db5d'),(2477,292,'CodeForBodywork','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'C\', @StageOfCompletion = \'V\'\r\nR2:VALUE IS PRESENT IF SpecialPurposeDesignation IS ABSENT\r\nR3:VALUE = /^(AA|AB|AC|AD|AE|AF|AG)$/\r\nR4:VALUE = /^(CA|CB|CC|CD|CE|CF|CG|CH|CI|CJ|CX)$/\r\nR5:VALUE = /^(BA|BB|BC|BE|BX)$/\r\nR6:VALUE = /^(DA|DB|DC|DE|DF|DG)$/\r\nR7:VALUE = /^(DB|DC|DE)$/','N','0','admin',NULL,'',NULL,'当车型= Nx, Ox, Rx, Sx 且 完成阶段=C（完整车）时必填\r\n当车型=Mx 且 SpecialPurposeDesignation has no value 且 完成阶段=C（完整车）时必填\r\n\r\nCodeForBodywork = AA, AB, AC, AD, AE, AF, AG where VehicleCategory = M1x\r\nCodeForBodywork = CA, CB, CC, CD, CE, CF, CG, CH, CI, CJ, CX where VehicleCategory = M2x, M3x\r\nCodeForBodywork = BA, BB, BC, BE, BX where VehicleCategory = N1x, N2x, N3x\r\nCodeForBodywork = DA, DB, DC, DE, DF, DG where VehicleCategory = Ox\r\nCodeForBodywork = DB, DC, DE where VehicleCategory = Rx, Sx\r\n\r\n当车型=Lx, Tx, Cx时禁止','maxLength=2','38.','DIRECT',34,'VALUE REGEX','认证系统','39feea53-347f-4e0a-82de-f720856e3624'),(2478,293,'Colour','String','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'C\', @StageOfCompletion = \'V\'','N','0','admin',NULL,'',NULL,'禁止 to state same value more then once\r\n当车型=M2x, M3x, N2x, N3x, Ox, Lx, Tx, Cx, Rx, Sx时禁止','maxLength=2','40.','DIRECT',34,'VALUE IS PRESENT IF','MES','f449fd1e-9fd4-4c86-a6a0-4d8c3158a6d8'),(2479,294,'NumberOfDoors','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nR2:VALUE IS PRESENT IF ConfigurationDoorsGroup IS PRESENT\r\nR3:VALUE = COALESCE(NumberOfDoorsFront, 0) + COALESCE(NumberOfDoorsLeft, 0) + COALESCE(NumberOfDoorsBack, 0) + COALESCE(NumberOfDoorsRight, 0)','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx 且 the ConfigurationDoorsGroup exists时必填\r\nThe sum of doors given in the ConfigurationDoorsGroup must be equal to NumberOfDoors\r\n\r\n当车型=Ox, L1x, L3x, L4x, Tx, Cx, Rx, Sx时禁止','min=0.0; max=99.0','41.','STRIP_UNIT',34,'VALUE IS PRESENT IF','认证系统','59d4db0a-00aa-4b08-95b7-0f8b412608f3'),(2480,295,'NumberOfDoorsFront','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Ox, L1x, L3x, L4x, Tx, Cx,  Rx, Sx时禁止','min=0.0; max=99.0','41.','DIRECT',34,'VALUE IS PRESENT','认证系统','049b65ce-1c2e-4a32-8f3f-8906fd7d4aa2'),(2481,296,'NumberOfDoorsLeft','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Ox, L1x, L3x, L4x, Tx, Cx,  Rx, Sx时禁止','min=0.0; max=99.0','41.','STRIP_UNIT:2',34,'VALUE IS PRESENT','认证系统','d6b288a7-4763-4980-8722-58a633755f3d'),(2482,297,'NumberOfDoorsRight','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Ox, L1x, L3x, L4x, Tx, Cx,  Rx, Sx时禁止','min=0.0; max=99.0','41.','STRIP_UNIT:2',34,'VALUE IS PRESENT','认证系统','2369e5c1-2bf2-454f-b6b5-3629298f1f23'),(2483,298,'NumberOfDoorsBack','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Ox, L1x, L3x, L4x, Tx, Cx,  Rx, Sx时禁止','min=0.0; max=99.0','41.','STRIP_UNIT',34,'VALUE IS PRESENT','认证系统','afd1f4d6-f7ab-4720-a3f1-7bb7a58295af'),(2484,299,'NumberOfSeatingPositionsIncludingDriver','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nR2:VALUE IN [1..9]\r\nR3:VALUE >= 10\r\nR4:VALUE IN [1..6]\r\nR5:VALUE IN [1..9]\r\nR6:VALUE IN [1, 2]\r\nR6a:VALUE IN [1,2] IF VehicleCategory IN [\'L3e\', \'L3e-A1\', \'L3e-A2\', \'L3e-A3\']\r\nR6b: VALUE = 1 IF VehicleCategory IN [/L3e-A.T/, /L3e-A.E/]\r\nR8:VALUE IN [1..4]\r\nR8a:VALUE IN [1..5] IF VehicleCategory = /L5e-A/\r\nR8b:VALUE IN [1..2] IF VehicleCategory = /L5e-B/\r\nR9a:VALUE IN [1..2] IF VehicleCategory IN [/L7e-A/, /L7e-B1/, /L7e-CU/]\r\nR9b:VALUE IN [1..3] IF VehicleCategory = /L7e-B2/','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Lx 且 完成阶段=C（完整车）时必填\r\n\r\nNumberOfSeatingPositionsIncludingDriver >=1 AND <= 9 where VehicleCategory = M1x\r\nNumberOfSeatingPositionsIncludingDriver >=10 where VehicleCategory = M2x, M3x\r\nNumberOfSeatingPositionsIncludingDriver  >=1 AND <= 6 where VehicleCategory = N1x\r\nNumberOfSeatingPositionsIncludingDriver >=1 AND <= 9 where VehicleCategory = N2x, N3x\r\nNumberOfSeatingPositionsIncludingDriver >=1 AND <= 2 where VehicleCategory = L1x, L2x\r\nNumberOfSeatingPositionsIncludingDriver >=1 AND <= 2 where VehicleCategory = L3e, L3e-A1, L3e-A2, L3e-A3\r\nNumberOfSeatingPositionsIncludingDriver = 1 WHERE VehicleCategory = L3e-A%T of L3e-A%E\r\nNumberOfSeatingPositionsIncludingDriver >=1 AND <= 4 where VehicleCategory = L4x\r\nNumberOfSeatingPositionsIncludingDriver >=1 AND <= 5 where VehicleCategory = L5e-A%\r\nNumberOfSeatingPositionsIncludingDriver >=1 AND <= 2 where VehicleCategory = L5e-B%\r\nNumberOfSeatingPositionsIncludingDriver >=1 AND <= 2 where VehicleCategory = L6x\r\nNumberOfSeatingPositionsIncludingDriver >=1 AND <= 2 where VehicleCategory = L7e-Ax\r\nNumberOfSeatingPositionsIncludingDriver >=1 AND <= 2 where VehicleCategory =L7e-B1\r\nNumberOfSeatingPositionsIncludingDriver >=1 AND <= 3 where VehicleCategory =L7e-B2\r\nNumberOfSeatingPositionsIncludingDriver >=1 AND <= 2  where VehicleCategory = L7e-CU\r\n\r\n当车型=Ox, Tx, Cx, Rx, Sx时禁止','min=0.0; max=999.0','42.','DIRECT',34,'VALUE IN','认证系统','a452a36e-9d23-43a9-ac92-b3eeeed814e3'),(2485,300,'NumberOfSeatsStationaryUseOnly','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'C\', @StageOfCompletion = \'V\'','N','0','admin',NULL,'',NULL,'当车型=Nx, Ox, Lx, Tx, Cx, Rx, Sx时禁止','min=0.0; max=999.0','42.1.',NULL,34,'VALUE IS PRESENT IF','认证系统','a36bd153-7bb6-4fca-b711-d84e78a48ea4'),(2486,301,'NumberOfWheelchairUserAccessiblePositions','Short','vehicle_attribute',NULL,'R1:VALUE IS PRESENT IF ANY @StageOfCompletion = \'C\', @StageOfCompletion = \'V\'','N','0','admin',NULL,'',NULL,'当车型=Nx, Ox, Lx, Tx, Cx, Rx en Sx时禁止','min=0.0; max=999.0','42.3.',NULL,34,'VALUE IS PRESENT IF','认证系统','fa417def-53a6-4885-8bef-35c51eaf52e6'),(2487,302,'SoundLevelStationary','Decimal','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nVALUE IS PRESENT IF EngineCapacity IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Lx; Tx, Cx 且 EngineCapacity has a value 且 完成阶段=C（完整车）, V时必填\r\n\r\n当车型=Ox, Rx, Sx时禁止','totalDigits=5; fractionDigits=2; min=0.0; max=999.99','46.','STRIP_UNIT',34,'VALUE IS PRESENT IF','认证系统','b3ae97f5-f50e-4f3e-8899-6c3ace383e01'),(2488,303,'SoundLevelStationaryEngineSpeed','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\r\nVALUE IS PRESENT IF EngineCapacity IS PRESENT','N','0','admin',NULL,'',NULL,'当车型=Mx, Nx, Lx; Tx, Cx 且 EngineCapacity has a value  且 完成阶段=C（完整车）, V时必填\r\n\r\n当车型=Ox, Rx, Sx时禁止','min=0.0; max=99999.0','46.','STRIP_UNIT:2',34,'VAL