 max=9999.99','27.1.','STRIP_UNIT',34,'VALUE IS PRESENT IF','认证系统','a31c8f5a-c576-4c20-ab8f-a38661b5a96a'),(2676,260,'EngineSpeedMaximumNetPower','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\nR2a:VALUE IS PRESENT IF @EngineCapacity IS PRESENT\nR2b:VALUE IS ABSENT IF @EngineCapacity IS ABSENT','N','0','admin','2026-05-12 10:18:01','',NULL,'当车型=Mx, Nx, Lx for the EnergyConvertor with an EngineCapacity时必填\r\nand EngineSpeedMaximumNetPowerMin / EngineSpeedMaximumNetPowerMax has no value 且 完成阶段=C（完整车）, V\r\n\r\n禁止 for the EnergyConvertor where EngineCapacity has no value\r\n禁止 for the EnergyConvertor where EngineSpeedMaximumNetPowerMin/EngineSpeedMaximumNetPowerMax has a value\r\n当车型=Ox, Tx, Cx, Rx, Sx时禁止','min=0.0; max=9999.99;totalDigits=6;fractionDigits=2','27.1.','STRIP_UNIT:2',34,'VALUE IS PRESENT','认证系统','083e2f52-6bf4-465f-97b0-19456da574eb'),(2677,261,'EngineSpeedMaximumNetPowerMin','Int','vehicle_attribute',NULL,'R1:VALUE IS PRESENT\nR2:VALUE IS ABSENT IF @EngineCapacity IS ABSENT','N','0','admin','2026-05-12 10:19:41','',NULL,'当车型=Mx, Nx, Lx for the EnergyConvertor with an EngineCapacity时必填\r\nand EngineSpeedMaximumNetPower has no value 且 完成阶段=C（完整车）, V\r\nEngineSpeedMaximumNetPowerMin &lt; EngineSpeedMaximumNetPowerMax\r\n\r\n禁止 for the EnergyConvertor where EngineSpeedMaximumNetPower has a value\r\n当车型=Ox, Tx, Cx, Rx, Sx时禁止\r\n禁止 for the EnergyConvertor where EngineCapacity has no value','min=0.0; max=99999.0',NULL,NULL,34,'VALUE IS ABSENT IF',NULL,'2267a0d7-56ef-40bf-8f06-beb7f31eedfd'),(2678,0,'工厂1000','1000','factory',NULL,NULL,'N','0','admin','2026-05-12 16:29:00','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2679,1,'工厂1001','1001','factory',NULL,NULL,'N','0','admin','2026-05-12 16:29:11','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2680,0,'车辆模版自动生效','1','auto_status',NULL,NULL,'N','0','admin','2026-05-13 10:53:07','admin','2026-05-13 16:29:17',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2681,1,'XML文件超时未上传提醒时间（毫秒）','86400000','reminder_time'