--
-- Table structure for table `sys_heartbeat_config`
--

DROP TABLE IF EXISTS `sys_heartbeat_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_heartbeat_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `country_code` varchar(10) DEFAULT NULL COMMENT '国家代码，NULL表示全局默认配置',
  `normal_interval` int NOT NULL DEFAULT '30' COMMENT '正常心跳间隔（秒），默认30s',
  `exception_interval` int NOT NULL DEFAULT '10' COMMENT '异常心跳间隔（秒），默认10s',
  `timeout_seconds` int NOT NULL DEFAULT '5' COMMENT '超时判定秒数，默认5s',
  `max_reconnect_times` int NOT NULL DEFAULT '3' COMMENT '单次最大重连次数，默认3次',
  `reconnect_interval` int NOT NULL DEFAULT '5' COMMENT '重连间隔（秒），默认5s',
  `reconnect_pause` int NOT NULL DEFAULT '60' COMMENT '重连失败后暂停时间（秒），默认60s',
  `notify_duration` int NOT NULL DEFAULT '10' COMMENT '异常持续X分钟后通知，默认10分钟',
  `notify_reconnect_times` int NOT NULL DEFAULT '10' COMMENT '重连超过X次后通知，默认10次',
  `disable_duration` int NOT NULL DEFAULT '30' COMMENT '持续重连失败X分钟后禁用接口，默认30分钟',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_country_code` (`country_code`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='心跳监测配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

