--
-- Table structure for table `sys_heartbeat_log`
--

DROP TABLE IF EXISTS `sys_heartbeat_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_heartbeat_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `account_id` bigint NOT NULL COMMENT '关联账号ID',
  `country_code` varchar(10) NOT NULL COMMENT '国家代码',
  `api_url` varchar(500) NOT NULL COMMENT '检测接口地址',
  `check_time` datetime NOT NULL COMMENT '心跳检测时间',
  `check_result` tinyint NOT NULL COMMENT '检测结果：0-正常，1-异常',
  `response_code` int DEFAULT NULL COMMENT 'HTTP响应状态码',
  `exception_type` varchar(100) DEFAULT NULL COMMENT '异常类型（TIMEOUT/LOGIN_EXPIRED/NETWORK_ERROR/CONFIG_MISMATCH）',
  `exception_msg` varchar(1000) DEFAULT NULL COMMENT '异常信息',
  `is_reconnect` tinyint NOT NULL DEFAULT '0' COMMENT '是否为重连记录：0-否，1-是',
  `reconnect_count` int DEFAULT NULL COMMENT '本次重连次数',
  `reconnect_result` tinyint DEFAULT NULL COMMENT '重连结果：0-成功，1-失败',
